window.ROUND_DATA = {"round": 76, "date": "2025.10.18", "problems": [{"n": 1, "a": 5, "p": 1, "e": "전삼국", "x": "", "k": "구석기 시대"}, {"n": 2, "a": 2, "p": 2, "e": "전삼국", "x": "", "k": "고구려"}, {"n": 3, "a": 3, "p": 2, "e": "삼국", "x": "삼국건국순서 및 전성기:\n• 고구려: 건국 2위, 전성기 5위\n• 백제: 건국 3위, 전성기 4위 (가장 먼저 전성기)\n• 신라: 건국 4위, 전성기 6위\n\n전개 과정:\n① 백제가 먼저 전성기를 맞아 고구려와 평양성 전투 → 고국원왕 전사\n② 그 다음 고구려가 전성기를 맞아 장수왕의 남하 정책으로 나제동맹 결성\n③ 신라와 백제의 황산벌 전투로 의자왕 전사", "k": "백제의 대외 항쟁"}, {"n": 4, "a": 1, "p": 1, "e": "삼국", "x": "• 금동대향로: 백제\n• 산수무늬벽돌: 백제\n• 금관: 신라", "k": "백제 금동 대향로"}, {"n": 5, "a": 4, "p": 2, "e": "남북국", "x": "통일신라 키워드: 촌락 문서, 서원경, 청해진", "k": "통일 신라 경제(민정 문서)"}, {"n": 6, "a": 2, "p": 2, "e": "남북국", "x": "신문왕의 업적:\n\n[왕권 강화]\n• 김흠돌의 난 진압\n• 진골귀족 숙청\n• 관료전 지급\n• 녹읍 폐지\n\n[체제 정비]\n• 9주 5소경\n• 9서당 10정: 고구려+백제+말갈인\n• 국학 설치\n\n[신격화]\n• 만파식적", "k": "신문왕"}, {"n": 7, "a": 4, "p": 2, "e": "삼국", "x": "의상 스님 키워드: 부석사 창건, 관음신앙, 화엄종", "k": "의상"}, {"n": 8, "a": 3, "p": 2, "e": "남북국", "x": "발해 키워드: 대봉예 ('대' 성씨), 5경 15부 62주", "k": "발해"}, {"n": 9, "a": 2, "p": 3, "e": "삼국", "x": "통일신라의 난 순서: 김흠돌의 난(초기) → 김헌창의 난(후기 초반) → 원종·애노의 난(후대)", "k": "신라 하대"}, {"n": 10, "a": 2, "p": 2, "e": "남북국", "x": "후삼국 전개 순서 (포공고신일):\n① 견훤의 신라 습격: 포석정\n② 공산 전투\n③ 고창 전투\n④ 신검의 난: 견훤 고려 귀순\n⑤ 신라 멸망\n⑥ 일리천 전투: 후삼국 통일", "k": "후삼국 통일 과정"}, {"n": 11, "a": 1, "p": 2, "e": "고려", "x": "예종 키워드:\n• 청연각, 보문각\n• 사람들 관학 듣게 함 (관학 진흥책)\n  - 국자감에 전문 강좌인 7재 개설", "k": "고려 예종"}, {"n": 12, "a": 3, "p": 3, "e": "고려", "x": "무신정권 집권자 요약:\n① 정중부: 이의방과 정변을 일으킴\n② 이의민: 조위총의 난 진압\n③ 최충헌: 봉사 10조를 올려 시정 개혁 요구\n④ 최우: 삼별초 편성, 정방(인사 행정 담당 기구) 설치\n   → 우리 무신 정권이 인사까지 다 해먹겠다 (권력)", "k": "최우"}, {"n": 13, "a": 5, "p": 2, "e": "고려", "x": "고려 경제 키워드:\n• 송, 일본, 동남아시아, 아라비아\n• 주전도감 설치\n• 해동통보, 은병\n• 삼한통보\n• 동국통보", "k": "고려 대외 무역"}, {"n": 14, "a": 4, "p": 2, "e": "고려", "x": "고려의 난과 역사 순서:\n\n① 왕규의 난\n  - 태조 왕건 사후 왕위 계승을 두고 혼란\n  - 왕건의 아들 혜종\n\n② 강조의 정변\n  - 성종 이후 국가 체계가 완비되었으나\n  - 그 이후 목종 때 국정을 못 돌봄\n  - 강조가 목종 폐위, 현종 왕 즉위, 이후 고려 전성기\n\n③ 이자겸의 난\n  - 목종 폐위 이후 고려 전성기\n  - 그러나 문벌귀족 권력 너무 강해짐\n  - 특히 이자겸, 그래서 인종이 견제함\n  - 이자겸의 인종 견제 차단 및 숙청\n  - 김부식이 제압함\n\n④ 묘청의 난\n  - 인종은 이자겸의 측근 척준경 회유\n  - 이자겸 실각\n  - 개경파(김부식) vs 서경파(묘청, 정지상)\n  - 서경 천도 운동\n  - 묘청의 난 → 김부식이 제압함\n\n⑤ 무신정변", "k": "고려 전기 정치 사건"}, {"n": 15, "a": 3, "p": 3, "e": "고려", "x": "개경 키워드:\n• 만월대: 고려 왕조의 궁궐터\n• 국자감, 성균관\n• 만부교: 거란이 보낸 낙타가 굶어 죽음\n\n강감찬: 개경 나성 축조", "k": "개성"}, {"n": 16, "a": 1, "p": 2, "e": "고려", "x": "대몽항쟁:\n• 박서: 귀주성\n• 김윤후: 충주성, 처인성\n• 강화도 천도\n• 팔만대장경\n• 죽주성, 다인철소", "k": "몽골 침입"}, {"n": 17, "a": 1, "p": 1, "e": "고려", "x": "고려 청자:\n• 아름다운 비색\n• 푸른색 유물이면 고려", "k": "고려 상형 청자"}, {"n": 18, "a": 3, "p": 1, "e": "고려", "x": "원 간섭기:\n• 변발, 호복\n• 응방: 매 기르는 곳 (원을 위한 공물)", "k": "충렬왕(원 간섭기)"}, {"n": 19, "a": 4, "p": 3, "e": "조선", "x": "세종의 잘 알려지지 않은 업적:\n• 박연의 편경\n• 정간보: 국악 악보\n• 삼강행실도: 훈민정음으로 편찬한 효도책", "k": "세종"}, {"n": 20, "a": 5, "p": 2, "e": "조선", "x": "연산군 키워드: 폐비 윤씨, 교동도 유배\n• 무오사화: 조의제문이 발단 → 김일손 등이 화를 입음\n\n[사화 정리]\n① 무오사화: 연산군 / 조의제문이 발단 / 김일손 피해\n② 갑자사화: 연산군 / 폐비 윤씨 빌미 / 신하 숙청\n③ 기묘사화: 중종 / 위훈삭제 시도 불만 / 조광조 축출", "k": "연산군"}, {"n": 21, "a": 1, "p": 2, "e": "조선", "x": "임진왜란 키워드:\n• 권율: 이치 전투\n• 정문부: 북관대첩", "k": "임진왜란"}, {"n": 22, "a": 2, "p": 2, "e": "조선", "x": "3사 (언론):\n• 사헌부\n• 사간원\n• 홍문관\n  - 옥당\n  - 도서 관장", "k": "홍문관"}, {"n": 23, "a": 5, "p": 1, "e": "조선", "x": "대동법:\n• 발단: 공물의 방납 폐단\n• 방법: 공물 대신 쌀(대동미)로 세금\n• 결과:\n  - 선혜청: 대동미 관리\n  - 공인 등장: 관청에 물품을 조달\n  - 상품 화폐 경제 발달", "k": "대동법"}, {"n": 24, "a": 4, "p": 2, "e": "조선", "x": "이익 키워드 (조선 후기):\n• 한전론: 특정 경작구역(영업전) 판매 제한\n• 곽우록\n• 여섯 가지 좀: 과거제, 노비제\n• 화폐 사용 금지: 폐전론", "k": "이익"}, {"n": 25, "a": 2, "p": 2, "e": "조선", "x": "영조 업적:\n• 신문고 재설치 (태종 때 처음 설치)\n• 속대전 편찬", "k": "영조"}, {"n": 26, "a": 3, "p": 2, "e": "조선", "x": "조선 후기 키워드: 사학(천주교) 박해 - 정약종, 정약용\n\n경제:\n• 상평통보 / 인삼 무역 / 고추, 담배 / 저잣거리 / 한글소설", "k": "신유박해"}, {"n": 27, "a": 3, "p": 1, "e": "조선", "x": "신윤복: 혜원 / 화풍으로 파악", "k": "신윤복"}, {"n": 28, "a": 2, "p": 3, "e": "개항기", "x": "최익현 키워드:\n• 상소문: 강화도 조약 반대\n• 개항 반대\n\n※ 쇄국(신미양요) ~ 개항(갑신정변) 사이 시기", "k": "최익현(왜양일체론)"}, {"n": 29, "a": 5, "p": 2, "e": "개항기", "x": "흥선대원군 키워드:\n• 경복궁 중건\n• 원납전 / 당백전\n• 호포제 / 사창제\n• 서원 철폐 / 비변사 폐지\n\n[쇄국기 사건 순서]\n① 병인양요: 한성근 - 문수산성\n② 제너럴 셔먼호\n③ 신미양요\n④ 척화비 / 통상수교 거부", "k": "흥선 대원군(경복궁 중건)"}, {"n": 30, "a": 1, "p": 2, "e": "개항기", "x": "임오군란 결과:\n• 조청상민수륙무역장정\n  - 임오군란 → 청이 진압 → 빌미로 장정 체결\n  - 청나라의 상행위 허용\n• 제물포 조약 (일본)", "k": "조청 상민 수륙 무역 장정"}, {"n": 31, "a": 3, "p": 1, "e": "개항기", "x": "동학농민운동 키워드:\n• 전봉준\n• 봉기\n• 집강소", "k": "동학 농민 운동"}, {"n": 32, "a": 4, "p": 2, "e": "개항기", "x": "독립협회 키워드:\n• 독립관\n• 독립신문 / 독립문\n• 만민공동회 / 관민공동회\n• 헌의 6조", "k": "독립 협회"}, {"n": 33, "a": 4, "p": 2, "e": "개항기", "x": "광무개혁 키워드:\n• 구본신참\n• 대한제국\n• 황제\n• 양지아문 / 지계아문\n• 양전사업\n• 지계: 토지 문서", "k": "광무개혁"}, {"n": 34, "a": 3, "p": 3, "e": "개항기", "x": "• 광혜원: 최초의 근대식 병원 - 알렌\n• 한성 전기 회사: 한성 전차", "k": "근대 문물"}, {"n": 35, "a": 5, "p": 2, "e": "개항기", "x": "을사늑약 이후 국권 수호 노력:\n• 을사의병: 최익현 / 신돌석\n• 헤이그 특사\n• 신민회: 안창호 / 대성학교\n• 안중근\n• 나철: 을사오적 처단 시도", "k": "을사늑약 이후 국권 수호 운동"}, {"n": 36, "a": 2, "p": 1, "e": "일제강점기", "x": "무단통치 시기 키워드:\n• 헌병 경찰\n• 태형\n• 교사: 제복 입고 칼을 참", "k": "무단 통치(1910년대)"}, {"n": 37, "a": 5, "p": 3, "e": "일제강점기", "x": "문화통치 시기 키워드:\n• 보통학교 6년\n• 민립대학 설립운동: 경성제국대학으로 견제", "k": "제2차 조선 교육령"}, {"n": 38, "a": 4, "p": 2, "e": "일제강점기", "x": "의열단 키워드:\n• 파괴왕\n• 김원봉\n• 조선 혁명 선언: 파괴 이념", "k": "의열단"}, {"n": 39, "a": 3, "p": 2, "e": "일제강점기", "x": "물산장려운동 키워드:\n• 자본가의 이익\n• 자작회, 토산 애용 부인회", "k": "물산 장려 운동"}, {"n": 40, "a": 3, "p": 2, "e": "일제강점기", "x": "신간회와 근우회 키워드:\n• 좌우 합작 민족 협동 전선\n• 1920년대", "k": "근우회"}, {"n": 41, "a": 1, "p": 2, "e": "일제강점기", "x": "대한민국 임시정부 키워드:\n• 한국광복군: 임시정부 산하 무장투쟁 조직\n• 독립공채\n• 삼균주의: 건국강령\n• 한일 관계 사료집", "k": "대한민국 임시 정부"}, {"n": 42, "a": 4, "p": 1, "e": "일제강점기", "x": "총동원령 시기 키워드:\n• 중일전쟁\n• 황국신민 서사\n• 여자 정신 근로령", "k": "중일 전쟁 이후"}, {"n": 43, "a": 4, "p": 2, "e": "일제강점기", "x": "일제강점기 사회 문화상:\n• 백화점\n• 몸뻬\n• 라디오 방송\n• 경평 축구 대회\n• 모던 걸, 신여성\n• 문화주택", "k": "일제 강점기 근대 문화"}, {"n": 44, "a": 5, "p": 3, "e": "일제강점기", "x": "여운형:\n• 좌우합작운동\n• 조선건국준비위원회\n  - 북한으로 흡수 / 키워드: 민족 해방", "k": "조선 건국 준비 위원회"}, {"n": 45, "a": 5, "p": 1, "e": "해방이후", "x": "제주 4·3 사건 키워드:\n• 남한 단독 선거 반대 세력 vs 토벌대\n• 진상 규명, 희생자 명예 회복 특별법\n  - 제주 4·3 사건\n  - 5·18 민주화 운동\n  - 부마 민주항쟁", "k": "제주 4·3 사건"}, {"n": 46, "a": 5, "p": 3, "e": "미분류", "x": "", "k": "내포 지역(예산·홍성)"}, {"n": 47, "a": 1, "p": 2, "e": "해방이후", "x": "개헌 역사:\n① 이승만 사사오입: 대통령에게만 중임 제한 적용 안 함\n② 박정희 유신헌법: 통일 주체 국민회의 간선제\n③ 전두환→노태우 6월 민주항쟁: 대통령 5년 단임제 - 현재", "k": "헌법 개정의 역사"}, {"n": 48, "a": 1, "p": 2, "e": "해방이후", "x": "박정희 정부 키워드:\n• 경부 고속도로\n• 서울 지하철 1호선", "k": "박정희 정부"}, {"n": 49, "a": 2, "p": 2, "e": "해방이후", "x": "노태우 정부 키워드:\n• 서울 88 올림픽\n• 7·7 선언\n• 남북한 유엔 동시 가입\n• 북방정책\n  - 배경: 소련 붕괴\n  - 한반도 비핵화 / 남북 기본 합의서\n  - 동구권 국가와 수교", "k": "노태우 정부"}, {"n": 50, "a": 5, "p": 3, "e": "미분류", "x": "", "k": "우리나라의 연호"}]};
